import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import{Yt as i}from"./chunks/assets.DAjhvrpn.js";var a=JSON.parse(`{"title":"Pupillometry","description":"","frontmatter":{"title":"Pupillometry","lang":"en-US"},"headers":[],"relativePath":"building/pupillometry.md","filePath":"building/pupillometry.md"}`),o={name:`building/pupillometry.md`};function s(n,a,o,s,c,l){return e(),r(`div`,null,[...a[0]||=[t(`<h1 id="pupillometry" tabindex="-1">Pupillometry <a class="header-anchor" href="#pupillometry" aria-label="Permalink to “Pupillometry”">​</a></h1><p>The pupillometry module consists of a monochrome camera mounted at the side of the screen, pointing at the side of the mouse&#39;s face. The lens frames the pupil in enough detail for markerless pose estimation software to process it. Its field of view also allows tracking sniffing and whisking, although that is beyond the scope of this building guide.</p><h2 id="camera-set-up" tabindex="-1">Camera setup <a class="header-anchor" href="#camera-set-up" aria-label="Permalink to “Camera setup”">​</a></h2><p>We use a Teledyne FLIR FFY-U3-04S2M-S camera; its small form factor lets us place it right below the aluminum plate holding the screen without taking up much space in the rig. It is a 0.4 MP, 121 FPS monochrome camera, used with an IR light source; a mono sensor is more sensitive and captures the details of the pupil better than a color sensor. Although pupillometry only needs 30 Hz, we chose the 0.4 MP, 121 FPS camera for flexibility in case we need other measurements (such as whisker movement). The 1.6 MP, 60 FPS camera should work fine for pupillometry and gives a higher image resolution.</p><ol><li>Make a 1&quot; hole in the screen at the position shown below. If you&#39;re adding a pupillometry module to an existing screen, first mark where the hole will go, then cut into the outer part of the screen with a precision knife (don&#39;t push the knife all the way through to the other side). Remove the outer part and then the Styrofoam with your fingers, down to the inner surface of the screen (the paint layer). Then cut through the paint layer from the inside with the precision knife. This way the hole is cleaner when seen from the inside and as small as possible (fitted to the diameter of the lens).</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Although the screen has a hole on one side, we didn&#39;t observe any behavioral impact in any of the pilot (or later) sessions, possibly because of its position and because the hole is fitted to the diameter of the lens.</p></div><figure><img src="`+i+`" alt="" width="1280" height="932" loading="lazy"></figure><ol start="2"><li>Set up the camera and position it on the aluminum plate.</li></ol><ol start="3"><li>Connect the camera to the computer.</li></ol><h2 id="light-source-set-up" tabindex="-1">Light source setup <a class="header-anchor" href="#light-source-set-up" aria-label="Permalink to “Light source setup”">​</a></h2><p>Explain how to set up the light source at the top of the rig.</p><h2 id="image-focus-and-camera-positioning" tabindex="-1">Image focus and camera positioning <a class="header-anchor" href="#image-focus-and-camera-positioning" aria-label="Permalink to “Image focus and camera positioning”">​</a></h2><p>Explain step by step how to focus the image and screw all the parts to get the camera in position.</p><h2 id="flir-spinnaker-support-installation-and-configuration-manual-in-matlab" tabindex="-1">Installing and configuring FLIR Spinnaker support in MATLAB <a class="header-anchor" href="#flir-spinnaker-support-installation-and-configuration-manual-in-matlab" aria-label="Permalink to “Installing and configuring FLIR Spinnaker support in MATLAB”">​</a></h2><h3 id="installation-instructions" tabindex="-1">Installation instructions <a class="header-anchor" href="#installation-instructions" aria-label="Permalink to “Installation instructions”">​</a></h3><ol><li><p><strong>Open MATLAB</strong>:</p><ul><li>Launch the MATLAB application on your computer.</li></ul></li><li><p><strong>Access Add-Ons</strong>:</p><ul><li>In the main MATLAB window, access the &quot;Add-Ons&quot; menu.</li></ul></li><li><p><strong>Search for and download FLIR Spinnaker Support</strong>:</p><ul><li>Use the search bar to find &quot;FLIR Spinnaker Support&quot;.</li><li>Check which version of MATLAB you have installed.</li><li>Download the corresponding version of the program by selecting the &quot;Full exe&quot; option.</li></ul></li><li><p><strong>Run the Program</strong>:</p><ul><li>Execute the downloaded installer.</li><li>Accept the terms and conditions of the software.</li><li>In the configuration section, select &quot;Application Developer&quot;.</li><li>Uncheck the &quot;GigE Driver&quot; option twice.</li><li>Proceed with the software installation.</li></ul></li><li><p><strong>Add the package to MATLAB</strong>:</p><ul><li>Open the directory of the downloaded package: <code>C:\\Users\\ephys\\AppData\\Roaming\\MathWorks\\MATLAB Add-Ons\\Toolboxes\\FLIR Spinnaker Support by Image Acquisition Toolbox\\FLIR Spinnaker Support by Image</code>.</li></ul></li><li><p><strong>Open the README File</strong>:</p><ul><li>Locate and open the &quot;README&quot; file in the package directory.</li><li>Apply the driver registry patch as instructed, making sure you use the patch for MATLAB R2022a.</li></ul></li><li><p><strong>Verification</strong>:</p><ul><li>Run all the steps described in the README file to verify that FLIR Spinnaker support works correctly.</li></ul></li><li><p><strong>Configure Rig Parameters</strong>:</p><ul><li>Return to the &quot;Rig Parameters&quot; configuration.</li><li>Add the necessary elements according to the specific instructions for your work environment.</li></ul></li></ol><h4 id="additional-note" tabindex="-1">Additional note <a class="header-anchor" href="#additional-note" aria-label="Permalink to “Additional note”">​</a></h4><p>Follow each step precisely and check that each component is compatible with your installed MATLAB version, to avoid issues during installation and configuration.</p><h2 id="explanation-of-the-processing-and-how-to-set-up-the-pipeline" tabindex="-1">Processing and pipeline setup <a class="header-anchor" href="#explanation-of-the-processing-and-how-to-set-up-the-pipeline" aria-label="Permalink to “Processing and pipeline setup”">​</a></h2><p>See the <a href="/software/pupillometry_guide.html">Pupillometry Pipeline Guide</a> for more information.</p>`,20)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};